from pathlib import Path
import json,hashlib,datetime,shutil
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'plan_b_analysis';EV=OUT/'audit_evidence';SCRIPTS=OUT/'scripts';FIG=OUT/'figures'
for p in [OUT,EV,SCRIPTS,FIG]:p.mkdir(parents=True,exist_ok=True)
SOURCE=ROOT/'reports/final_model_selection_20261016/four_income_group_final_dataset.csv'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
if not (EV/'protected_before.json').exists():
 protected={}
 for folder in ['econometric_results','second_stage_econometric_results','second_stage_investigation_20261016','fsqca_preparation_20261016','fsqca_results_20261016']:
  for p in (ROOT/folder).iterdir():
   if p.is_file():protected[str(p)]=sha(p)
 protected[str(SOURCE)]=sha(SOURCE)
 for p in (ROOT/'fsqca_results_20261016/audit_evidence').glob('*.json'):protected[str(p)]=sha(p)
 (EV/'protected_before.json').write_text(json.dumps(protected,indent=2),encoding='utf-8')
plan={'frozen_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source':str(SOURCE),'source_sha256':sha(SOURCE),'scope':'Bounded exploratory Plan B; no new variables, finance downloads, fsQCA or threshold search','annual_primary':'Frozen sample_B_Bank_credit, 1104 observations/137 countries, 2014–2023. Six X: uncentred bank private credit/GDP, RQ, ln real GDPpc, ln population, trade/GDP, inflation. y=log1p(million constant2022USD commitments).','within_between':'Every X split x−country mean and country mean on actual estimation observations. Country means of included year indicators added for unbalanced observation profiles. Raw calendar-year indicators retained. Country means are not means of the entire source grid or imputed records. No income interaction or extra mechanism regression.','estimators':'Annual matched TWFE OLS, augmented Mundlak OLS, random-intercept Gaussian CRE REML (nlme). Random effect conditioned on all X means and calendar observation-profile means. All country-cluster CR2/Satterthwaite; nlme uses fitted random-intercept covariance target, lm identity target. Independent Python reproduces each target via whitened CR2 and profiles REML variance ratio.','outcomes':{'absolute':'log1p(mean annual selected public commitments, million constant2022USD); for annual records original log1p(million2022USD)','per_capita':'log1p(mean annual [commitments_million*1e6/population], constant2022USD/person/year); not a population-weighted ratio of sums or total renewable investment'},'windows_main':[[2014,2015],[2016,2017],[2018,2019],[2020,2021],[2022,2023]],'windows_sensitivity':[[2014,2016],[2017,2019],[2020,2022]],'window_rules':'Non-overlap; require every calendar year of financing, population, GDPpc, FD, RQ, trade and inflation. No missing-as-zero or partial means. Mean FD/RQ/trade/inflation; arithmetic mean of annual lnGDPpc and lnPopulation. Same covariates used for absolute and per-capita outcomes. Income context is historical first year of each window, changes flagged. No pretending country-window is a country-year. Require at least2 usable windows per country and2 countries per window iteratively. Calendar-window effects replace individual calendar-year effects after aggregation.','window_models':'Two- and three-year TWFE absolute and per-capita, plus two-year CRE both outcomes. For each horizon/outcome refit annual TWFE on exactly the same country-years contributing to eligible aggregate windows; no unmatched claims that aggregation improves identification. Three-year analysis excludes2023 by design, not outcome inspection.','annual_sensitivities':'Complete10-year-history annual TWFE/CRE absolute; one-calendar-year lag of all six X using only frozen2014–2023 source (outcome2015–2023); matched TWFE/CRE absolute. Annual per-capita TWFE/CRE on original1104 support. No other transformations, windows, controls or trimming.','primary_multiple_testing_family':'Eight coefficient tests: annual CRE W_FD,B_FD,W_RQ,B_RQ; two-year TWFE FD,RQ for each outcome. Holm8, alongside unadjusted p/CR2 CI. Two annual CRE within-minus-between FD/RQ contrasts Holm2 separately. All other coefficients/sensitivities exploratory descriptive and unadjusted, not primary confirmations.','joint_tests':'Annual CRE B−W jointly zero for all six X (Mundlak restriction) using HTZ, and FD/RQ differences individually; report low degrees of freedom or singular tests.','robustness':'No variable search. Prespecified balanced-history and lag models, alternate outcome and three-year windows. All-country-deletion coefficient checks for annual CRE absolute (variance components held fixed in clearly labelled conditional FGLS diagnostic), and two-year TWFE absolute. No deletion chosen to improve significance. No bootstrap claimed; CR2 is primary robust inference, no nonlinear PPML or additional fsQCA authorized here.','diagnostics':'Within/between variance accounting with identity totalSS=withinSS+betweenSS; unweighted country-mean dispersion distinguished from observation-weighted betweenSS. Country-year, country and observed annual peak concentration, nonoverlap within-country timing proxies; no project size or provider share inferable from country totals. Published zeros vs unknown missingness retained. Country cluster influence from design geometry; low effective clusters and large shares flagged.','identification':'All between-country associations and selection differences descriptive, potentially confounded by recipient/provider selection. Unbalanced-profile terms restore algebraic within equivalence, not ignorability of missing reporting. No causal interpretation from new nominal significance.'}
if not (EV/'preanalysis_plan_frozen.json').exists():(EV/'preanalysis_plan_frozen.json').write_text(json.dumps(plan,indent=2),encoding='utf-8')
assert json.loads((EV/'preanalysis_plan_frozen.json').read_text())['source_sha256']==sha(SOURCE),'Frozen Plan B source hash changed'
